function formatWhen(value) { const date = new Date(value); return `${date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })} ${date.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}`; }
function directoryStatusText(sync) { if (sync.state === 'ok') return `${sync.sample ? 'Sample staff (development only)' : 'Synced from Microsoft'} at ${formatWhen(sync.lastSuccessAt)} · ${sync.people} people · syncs every 30 minutes`; if (sync.state === 'waiting-consent') return 'Waiting for admin consent in Azure (User.Read.All). Until then, people appear here when they first try to sign in.'; if (sync.state === 'error') return `Last sync failed: ${sync.message}`; return 'Not synced from Microsoft yet.'; }
function userBadges(user) { const badges = []; if (user.sample) badges.push('Sample'); if (!user.accountEnabled) badges.push('Disabled in Microsoft'); if (user.syncedAt && !user.inDirectory) badges.push('No longer in Microsoft'); if (!user.included && user.lastLoginAt) badges.push(`Tried to sign in ${formatWhen(user.lastLoginAt)}`); return badges.map((badge) => `<span class="user-badge">${esc(badge)}</span>`).join(''); }
function userListRowTemplate(user, asDirectory) { const canEdit = isAdmin(); const isSelf = user.id === currentUserId; const included = !asDirectory || user.included; const includeCell = asDirectory ? `<td><input type="checkbox" data-include-id="${esc(user.id)}" aria-label="${esc(user.name)} in Time Slide" ${user.included ? 'checked' : ''} ${isSelf || (user.included && user.userType === 'admin') ? 'disabled title="Admins stay in Time Slide. Change their user type first."' : !isAdmin() && user.included && user.userType !== 'user' ? 'disabled title="Only an admin can take a Manager or Admin out of Time Slide."' : ''}></td>` : ''; const nameCell = asDirectory ? `<td><strong class="user-name">${esc(user.name || user.email)}</strong>${user.jobTitle ? `<span class="user-sub">${esc(user.jobTitle)}</span>` : ''}${userBadges(user)}</td>` : `<td>${esc(user.name)}</td>`; return `<tr class="${included ? '' : 'is-excluded'}">${includeCell}${nameCell}<td>${esc(user.email)}</td>${asDirectory ? `<td>${esc(user.department)}</td>` : ''}<td><select data-user-id="${esc(user.id)}" data-user-list-field="userType" ${canEdit && !isSelf && included ? '' : 'disabled'}>${userTypeOptionsHtml(user.userType || 'user')}</select></td><td><select data-user-id="${esc(user.id)}" data-user-list-field="costCentre" ${canEdit ? '' : 'disabled'}>${costCentreOptionsHtml(user.costCentre || '')}</select></td><td>${patternCellHtml(user, included)}</td></tr>`; }
