function visibleDirectoryPeople() { const search = $('#directory-search').value.trim().toLowerCase(); const filter = $('#directory-filter').value; return directory.people.filter((user) => (filter === 'all' || (filter === 'in') === user.included) && (!search || [user.name, user.email, user.department, user.jobTitle].some((value) => (value || '').toLowerCase().includes(search)))).sort((a, b) => (b.included - a.included) || (a.name || '').localeCompare(b.name || '')); }
function renderUserList() { const rows = $('#user-rows'); if (!rows) return; const asDirectory = managesPeople() && Boolean(directory); $('#directory-tools').classList.toggle('is-hidden', !managesPeople()); $('#directory-sync').classList.toggle('is-hidden', !isAdmin()); $('#directory-status').classList.toggle('is-hidden', !asDirectory); document.querySelectorAll('.directory-col').forEach((cell) => cell.classList.toggle('is-hidden', !asDirectory)); $('#users-heading').textContent = isAdmin() ? 'Staff from Microsoft — tick who uses Time Slide' : isManager() ? 'Your team from Microsoft — tick who uses Time Slide' : 'People in Time Slide'; if (asDirectory) $('#directory-status').textContent = directoryStatusText(directory.sync); const people = asDirectory ? visibleDirectoryPeople() : [...state.users].sort((a, b) => a.name.localeCompare(b.name, 'en', { sensitivity: 'base' })); rows.innerHTML = people.length ? people.map((user) => userListRowTemplate(user, asDirectory)).join('') : `<tr><td colspan="7" class="list-empty">${asDirectory ? 'Nobody matches.' : 'Nobody has been added to Time Slide yet.'}</td></tr>`; rows.querySelectorAll('[data-include-id]').forEach((box) => box.addEventListener('change', () => { api('PUT', `/api/users/${encodeURIComponent(box.dataset.includeId)}/included`, { included: box.checked }).then((saved) => { Object.assign(directory.people.find((item) => item.id === saved.id), saved); showToast(saved.included ? `${saved.name} added to Time Slide${saved.workingPatternAdded ? ` on ${saved.workingPatternAdded}` : ''}` : `${saved.name} removed from Time Slide`); renderUserList(); reloadState(); }).catch((error) => { showToast(error.message); renderUserList(); }); })); rows.querySelectorAll('[data-pattern-user]').forEach((select) => select.addEventListener('change', () => { api('PUT', `/api/users/${encodeURIComponent(select.dataset.patternUser)}/working-pattern`, { patternId: select.value }).then((saved) => { const user = state.users.find((item) => item.id === saved.id); if (user) user.patternId = saved.patternId; const pattern = state.workingPatterns.find((item) => item.id === saved.patternId); showToast(pattern ? `${user?.name || 'They'} now on ${pattern.name}` : `${user?.name || 'They'} now have no working pattern`); afterPatternsChanged(); }).catch((error) => { showToast(error.message); renderUserList(); }); })); rows.querySelectorAll('[data-user-list-field]').forEach((input) => input.addEventListener('change', () => { const field = input.dataset.userListField; api('PUT', `/api/users/${encodeURIComponent(input.dataset.userId)}/${field === 'userType' ? 'user-type' : 'cost-centre'}`, { [field]: input.value }).then((saved) => { [state.users.find((item) => item.id === saved.id), directory?.people.find((item) => item.id === saved.id)].filter(Boolean).forEach((user) => Object.assign(user, { userType: saved.userType, costCentre: saved.costCentre })); showToast('User updated'); renderUserList(); }).catch((error) => { showToast(error.message); renderUserList(); }); })); }
// Setup -> Configuration (admins only): how Time Slide reaches Syspro. Saved passwords never come back from the server -- a blank password box keeps the saved one.
const CONFIG_TEXT = { 'config-enet-url': 'enetUrl', 'config-enet-operator': 'enetOperator', 'config-enet-company': 'enetCompanyId', 'config-sql-server': 'sqlServer', 'config-sql-port': 'sqlPort', 'config-sql-database': 'sqlDatabase', 'config-sql-user': 'sqlUser' };
