const CONFIG_CHECKS = { 'config-sql-encrypt': 'sqlEncrypt', 'config-sql-trust': 'sqlTrustServerCertificate' };
let sysproConfig = null;
let configDirty = false;
function setConfigDirty(dirty) { configDirty = dirty; $('#config-save').disabled = !dirty; }
function renderSysproConfig() { Object.entries(CONFIG_TEXT).forEach(([id, field]) => { $(`#${id}`).value = sysproConfig[field] ?? ''; }); Object.entries(CONFIG_CHECKS).forEach(([id, field]) => { $(`#${id}`).checked = Boolean(sysproConfig[field]); }); Object.entries(CONFIG_PASSWORDS).forEach(([id, field]) => { const saved = sysproConfig[`${field}Set`]; const input = $(`#${id}`); input.value = ''; input.placeholder = saved ? 'Saved — leave blank to keep' : 'Not set'; document.querySelector(`[data-remove-password="${id}"]`).classList.toggle('is-hidden', !saved); }); $('#config-updated').textContent = sysproConfig.updatedAt ? `Last changed ${formatWhen(sysproConfig.updatedAt)}${sysproConfig.updatedBy ? ` by ${sysproConfig.updatedBy}` : ''}` : 'Not filled in yet'; setConfigDirty(false); }
async function loadSysproConfig() { try { sysproConfig = await api('GET', '/api/config/syspro'); renderSysproConfig(); } catch (error) { showToast(`Could not load configuration: ${error.message}`); } }
function sysproFormValues() { const body = {}; Object.entries(CONFIG_TEXT).forEach(([id, field]) => { body[field] = $(`#${id}`).value.trim(); }); body.sqlPort = Number(body.sqlPort) || 1433; Object.entries(CONFIG_PASSWORDS).forEach(([id, field]) => { if ($(`#${id}`).value) body[field] = $(`#${id}`).value; }); Object.entries(CONFIG_CHECKS).forEach(([id, field]) => { body[field] = $(`#${id}`).checked; }); return body; }
