const previewFiltersActive = () => Object.values(previewFilters).some(Boolean);
const previewFilteredBlocks = () => previewData.blocks.filter((block) => PREVIEW_FILTERS.every((filter) => !previewFilters[filter.key] || filter.value(block) === previewFilters[filter.key]));
const previewHours = (seconds) => (seconds / 3600).toFixed(2);
